mapper.select:
SELECT instance.id, instance.object_type, instance.subject_id
  FROM approval_instance instance
 WHERE instance.tenant_id = #{tenantId}


        AND EXISTS (
            SELECT 1
              FROM approval_review_task task
             WHERE task.tenant_id = instance.tenant_id
               AND task.instance_id = instance.id
               AND task.assigned_actor_id = #{memberId}
               AND task.status = 'PENDING'
        )


        AND EXISTS (
            SELECT 1
              FROM approval_review_task task
             WHERE task.tenant_id = instance.tenant_id
               AND task.instance_id = instance.id
               AND task.assigned_actor_id = #{memberId}
               AND task.status IN ('APPROVED', 'REJECTED', 'TRANSFERRED')
        )


        AND instance.applicant_actor_id = #{memberId}


        AND EXISTS (
            SELECT 1
              FROM approval_instance_watcher watcher
             WHERE watcher.tenant_id = instance.tenant_id
               AND watcher.instance_id = instance.id
               AND watcher.actor_id = #{memberId}
        )



    AND instance.status = #{status}


    AND instance.object_type = #{objectType}


    AND instance.subject_id = #{subjectId}


    AND instance.object_type <> 'OA_REQUEST'
    AND instance.title LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'

 ORDER BY instance.updated_time DESC, instance.id DESC

SELECT instance.subject_id AS subjectId, instance.status
  FROM approval_instance instance
  INNER JOIN (
        SELECT subject_id, MAX(id) AS instance_id
          FROM approval_instance
         WHERE tenant_id = #{tenantId}
           AND object_type = #{objectType}
           AND subject_id IN

                #{subjectId}

         GROUP BY subject_id
  ) latest ON latest.instance_id = instance.id
 WHERE instance.tenant_id = #{tenantId}
